class Solution:
    def expressiveWords(self, s: str, words: List[str]) -> int:
        def rle(t):
            res = []
            i = 0
            while i < len(t):
                j = i
                while j < len(t) and t[j] == t[i]:
                    j += 1
                res.append((t[i], j - i))
                i = j
            return res

        gs = rle(s)
        ans = 0
        for w in words:
            gw = rle(w)
            if len(gw) != len(gs):
                continue
            ok = True
            for (c1, n1), (c2, n2) in zip(gs, gw):
                if c1 != c2 or not (n1 == n2 or (n1 >= 3 and n1 > n2)):
                    ok = False
                    break
            ans += ok
        return ans

