class Solution {
public:
    vector<pair<char,int>> rle(const string& t) {
        vector<pair<char,int>> res;
        int i = 0;
        while (i < (int)t.size()) {
            int j = i;
            while (j < (int)t.size() && t[j] == t[i]) j++;
            res.push_back({t[i], j - i});
            i = j;
        }
        return res;
    }
    int expressiveWords(string s, vector<string>& words) {
        auto gs = rle(s);
        int ans = 0;
        for (auto& w : words) {
            auto gw = rle(w);
            if (gw.size() != gs.size()) continue;
            bool ok = true;
            for (int k = 0; k < (int)gs.size(); k++) {
                char c1 = gs[k].first, c2 = gw[k].first;
                int n1 = gs[k].second, n2 = gw[k].second;
                if (c1 != c2 || !(n1 == n2 || (n1 >= 3 && n1 > n2))) { ok = false; break; }
            }
            if (ok) ans++;
        }
        return ans;
    }
};

