class Solution:
    def expressiveWords(self, s: str, words: List[str]) -> int:
        def stretchy(w):
            i = j = 0
            while i < len(s) and j < len(w):
                if s[i] != w[j]:
                    return False
                si, sj = i, j
                while i < len(s) and s[i] == s[si]:
                    i += 1
                while j < len(w) and w[j] == w[sj]:
                    j += 1
                n1, n2 = i - si, j - sj
                if n1 != n2 and not (n1 >= 3 and n1 > n2):
                    return False
            return i == len(s) and j == len(w)

        return sum(stretchy(w) for w in words)

